const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/meeting_attendee_records',
  qs: {project_id: 'SOME_INTEGER_VALUE', meeting_id: 'SOME_INTEGER_VALUE'},
  headers: {'content-type': 'application/json'},
  body: {meeting_attendee_record: {status: 'Present', login_information_id: 999}},
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/meeting_attendee_records?project_id=SOME_INTEGER_VALUE&meeting_id=SOME_INTEGER_VALUE"),
    Content = new StringContent("{\"meeting_attendee_record\":{\"status\":\"Present\",\"login_information_id\":999}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

